export type SiteAnswer = Record<string, unknown> & { offers: { name: string; price: string | null }[] };
export type Site = { name: string; website: string; raw?: boolean; pages: Record<string, string>; truth: number; answer: (id: { [k: string]: string }) => SiteAnswer };
const claim = (value: string, documentId: string, quote = value) => ({ field: 'claim' as const, value, documentId, quote });
const aud = (value: string, documentId: string, quote = value) => ({ field: 'audience' as const, value, documentId, quote });
